CREATE DATABASE IF NOT EXISTS quillo_aprende CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE quillo_aprende;
CREATE TABLE IF NOT EXISTS niveles(id_nivel INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS areas(id_area INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS subareas(id_subarea INT PRIMARY KEY AUTO_INCREMENT,id_area INT NOT NULL,nombre VARCHAR(80) NOT NULL,UNIQUE KEY uk_subarea(id_area,nombre),CONSTRAINT fk_subarea_area FOREIGN KEY(id_area) REFERENCES areas(id_area));
CREATE TABLE IF NOT EXISTS usuarios(id_usuario INT PRIMARY KEY AUTO_INCREMENT,nombre VARCHAR(120) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(200) NOT NULL,rol ENUM('docente','admin') NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS materiales(id_material INT PRIMARY KEY AUTO_INCREMENT,titulo VARCHAR(180) NOT NULL,descripcion VARCHAR(500) NOT NULL,contenido TEXT NOT NULL,ficha TEXT NOT NULL,id_nivel INT NOT NULL,id_area INT NOT NULL,id_subarea INT NOT NULL,creado_por INT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_mat_nivel FOREIGN KEY(id_nivel) REFERENCES niveles(id_nivel),CONSTRAINT fk_mat_area FOREIGN KEY(id_area) REFERENCES areas(id_area),CONSTRAINT fk_mat_subarea FOREIGN KEY(id_subarea) REFERENCES subareas(id_subarea),CONSTRAINT fk_mat_user FOREIGN KEY(creado_por) REFERENCES usuarios(id_usuario) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS retos_evaluaciones(id_pregunta INT PRIMARY KEY AUTO_INCREMENT,id_material INT NOT NULL,pregunta VARCHAR(500) NOT NULL,opcion_a VARCHAR(255) NOT NULL,opcion_b VARCHAR(255) NOT NULL,opcion_c VARCHAR(255) NOT NULL,opcion_d VARCHAR(255) NOT NULL,respuesta_correcta VARCHAR(255) NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,CONSTRAINT fk_reto_mat FOREIGN KEY(id_material) REFERENCES materiales(id_material) ON DELETE CASCADE);
